import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"正","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-正.md","filePath":"50-概念资料/dict-正.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-正.md"};function i(d,t,h,c,u,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="正" tabindex="-1">正 <a class="header-anchor" href="#正" aria-label="Permalink to &quot;正&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：正法 | 道家对应：正道</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;正&quot;就是<strong>不偏不倚，自利利他</strong>。不是绝对的&quot;对&quot;，而是在具体情境中，对涉事各方的整体利益都有益的那种行为。</p><p>了空居士强调：正不是一成不变的公式——武松打虎在宋代是正的（为民除害），现代人打虎就不正了。正的标准由<strong>整体观</strong>来定：&quot;对大众整体有益就是善（正），有害就是恶（不正）。&quot;</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;什么叫做正，不偏不倚谓之正。自利利他的行为，损人利已或损已利人的都不是那么正。&quot; — 答疑专辑2014_佛道</p></blockquote><blockquote><p>&quot;善恶有标准——以整体观来定，对大众整体有益就是善，有害就是恶。&quot; — <a href="/60-原文段落/论坛-整体观定善恶">论坛-整体观定善恶</a></p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>正就是合乎规矩</td><td>规矩是因时因地而变的，正的标准是整体利益</td></tr><tr><td>正反两面，选谁都行</td><td>在具体时空点上有客观的正，不是无所谓</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-恕">dict-恕</a> — 恕（己所不欲勿施于人）是判断&quot;正&quot;的底线标准</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 以恭敬心待人，行为自然趋于正</li><li><a href="/50-概念资料/dict-中道">dict-中道</a> — 正就是中道在伦理判断中的体现</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 正就是中道在伦理判断中的体现</li><li><a href="/meta-整体观">meta-整体观</a> — 以整体观定善恶，即是以整体观定&quot;正&quot;</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>做事前问自己：这件事对我是有利的，对别人是有利还是有害？对整体是有利还是有害？用道理和良心去判断。</p>',16)])])}const b=a(l,[["render",i]]);export{q as __pageData,b as default};
